function drawBackground(){
 const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#111a35');sky.addColorStop(.55,'#252341');sky.addColorStop(1,'#111827');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // dusk glow and moon
 const glow=ctx.createRadialGradient(640,265,8,640,265,410);glow.addColorStop(0,'#f9758e29');glow.addColorStop(1,'#f9758e00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,590);
 ctx.fillStyle='#ffe3ba';ctx.globalAlpha=.78;ctx.beginPath();ctx.arc(1038,146,40,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 // stars
 for(let i=0;i<52;i++){let x=(i*173+59)%W,y=(i*91+26)%292;ctx.globalAlpha=.2+(Math.sin(elapsed*1.1+i)*.15+.15);ctx.fillStyle='#b9dbff';ctx.fillRect(x,y,2,2)}ctx.globalAlpha=1;
 // skyline layers
 for(let layer=0;layer<3;layer++){let base=448+layer*42;for(let i=0;i<13;i++){let x=i*112-23+(layer%2)*28,w=randNo(i,42,82),h=randNo(i+layer*17,95,250)*(layer===0?.85:1);ctx.fillStyle=['#202746','#19213a','#151d32'][layer];ctx.fillRect(x,base-h,w,h);ctx.fillStyle=layer===0?'#344466':'#293555';ctx.fillRect(x+5,base-h+8,Math.max(3,w-10),3);for(let wy=base-h+22;wy<base-9;wy+=22)for(let wx=x+9;wx<x+w-5;wx+=15){if(((Math.floor(wx+wy)+i*7)%4)!==0){ctx.globalAlpha=.27+(((i*wx+wy)|0)%3)*.1;ctx.fillStyle=(i+layer)%3?'#5ad7dc':'#ffb566';ctx.fillRect(wx,wy,4,7)}}ctx.globalAlpha=1}}
 // rooftop distant neon architecture
 ctx.fillStyle='#131b2b';ctx.fillRect(0,448,W,48);ctx.fillStyle='#35415c';ctx.fillRect(0,448,W,3);
 ctx.strokeStyle='#ff547c';ctx.lineWidth=3;ctx.shadowColor='#ff426b';ctx.shadowBlur=14;ctx.strokeRect(93,331,166,78);ctx.shadowBlur=0;ctx.fillStyle='#ff8198';ctx.font='900 22px system-ui';ctx.textAlign='center';ctx.fillText('龍 · CLUB',176,379);
 ctx.strokeStyle='#37ddec';ctx.lineWidth=2;ctx.shadowColor='#37ddec';ctx.shadowBlur=12;ctx.strokeRect(1010,343,170,67);ctx.shadowBlur=0;ctx.fillStyle='#66eef2';ctx.font='800 16px system-ui';ctx.fillText('NIGHT / CITY',1095,383);ctx.textAlign='left';
 // rooftop platform
 const roof=ctx.createLinearGradient(0,480,0,720);roof.addColorStop(0,'#343c53');roof.addColorStop(.13,'#242b3d');roof.addColorStop(1,'#111827');ctx.fillStyle=roof;ctx.fillRect(0,492,W,H-492);
 ctx.fillStyle='#78839b';ctx.fillRect(0,492,W,3);ctx.fillStyle='#36cbd7';ctx.globalAlpha=.65;ctx.fillRect(0,496,W,2);ctx.globalAlpha=1;
 ctx.strokeStyle='#48536b';ctx.lineWidth=1;for(let x=0;x<W;x+=104){ctx.beginPath();ctx.moveTo(x,494);ctx.lineTo(x-72,H);ctx.stroke()}for(let y=532;y<H;y+=48){ctx.globalAlpha=.35;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.globalAlpha=1;
 // floor lights
 for(let x=48;x<W;x+=96){ctx.fillStyle='#62718a';ctx.fillRect(x,488,18,4);ctx.fillStyle='#45e7eb';ctx.globalAlpha=.6;ctx.fillRect(x+3,486,12,2);ctx.globalAlpha=1}
 const shade=ctx.createLinearGradient(0,0,0,H);shade.addColorStop(0,'#080b1a00');shade.addColorStop(1,'#080b1a80');ctx.fillStyle=shade;ctx.fillRect(0,0,W,H);
}
function randNo(seed,min,max){let v=Math.sin(seed*127.1+311.7)*43758.5453;return min+(v-Math.floor(v))*(max-min)}
function drawHUD(){
 // top panels
 ctx.fillStyle='#090d1bdc';rr(26,24,485,91,12);ctx.fill();rr(769,24,485,91,12);ctx.fill();ctx.strokeStyle='#ffffff1c';ctx.lineWidth=1;rr(26.5,24.5,484,90,12);ctx.stroke();rr(769.5,24.5,484,90,12);ctx.stroke();
 ctx.textAlign='left';ctx.fillStyle='#f0f7ff';ctx.font='900 21px system-ui';ctx.fillText('VOLT',48,58);ctx.fillStyle='#82a3b2';ctx.font='800 10px system-ui';ctx.fillText('THE CIRCUIT BREAKER',49,77);ctx.fillStyle='#8c9ab4';ctx.font='800 10px system-ui';ctx.fillText('P1',48,101);
 ctx.textAlign='right';ctx.fillStyle='#f0f7ff';ctx.font='900 21px system-ui';ctx.fillText('KIRA',1232,58);ctx.fillStyle='#b99ca9';ctx.font='800 10px system-ui';ctx.fillText('THE RED TEMPEST',1231,77);ctx.fillStyle='#8c9ab4';ctx.font='800 10px system-ui';ctx.fillText('CPU',1232,101);
 const bx=95,by=38,bw=390,bh=19;ctx.fillStyle='#222a3c';rr(bx,by,bw,bh,7);ctx.fill();let pRatio=player.hp/player.maxHp;ctx.fillStyle=pRatio<.28?'#ff536e':'#31dce3';rr(bx,by,bw*pRatio,bh,7);ctx.fill();ctx.fillStyle='#ffffff';ctx.globalAlpha=.18;rr(bx+2,by+2,bw*pRatio-4,5,3);ctx.fill();ctx.globalAlpha=1;
 ctx.save();ctx.translate(W,0);ctx.scale(-1,1);ctx.fillStyle='#222a3c';rr(bx,by,bw,bh,7);ctx.fill();let eRatio=enemy.hp/enemy.maxHp;ctx.fillStyle=eRatio<.28?'#ff536e':'#ff527a';rr(bx,by,bw*eRatio,bh,7);ctx.fill();ctx.fillStyle='#ffffff';ctx.globalAlpha=.16;rr(bx+2,by+2,bw*eRatio-4,5,3);ctx.fill();ctx.globalAlpha=1;ctx.restore();
 // special meters + timer
 ctx.fillStyle='#1b2639';rr(95,87,244,6,3);ctx.fill();rr(941,87,244,6,3);ctx.fill();ctx.fillStyle='#ffd073';ctx.fillRect(95,87,244,6);ctx.fillStyle='#ffd073';ctx.fillRect(941,87,244,6);
 ctx.fillStyle='#101629';rr(580,22,120,74,14);ctx.fill();ctx.strokeStyle='#ffc96c77';rr(580.5,22.5,119,73,14);ctx.stroke();ctx.textAlign='center';ctx.fillStyle='#ffc96c';ctx.font='900 10px system-ui';ctx.fillText('ROUND  '+round,640,41);ctx.fillStyle='#f6f7ff';ctx.font='900 34px ui-monospace,monospace';ctx.fillText(String(Math.ceil(roundTime)).padStart(2,'0'),640,76);ctx.fillStyle='#94a2bc';ctx.font='800 8px system-ui';ctx.fillText('ROOFTOP ARENA',640,89);
}

