function drawFighter(f){
 const face=f.facing,walk=Math.sin(f.walk)*5,duck=f.crouch?13:0,attack=f.attack?.type,active=f.attack?f.attack.t/f.attack.duration:0;
 ctx.save();ctx.translate(f.x,f.y);if(f.invuln>0&&Math.floor(elapsed*24)%2===0)ctx.globalAlpha=.48;
 // grounded shadow
 ctx.globalAlpha*=.28;ctx.fillStyle='#05070f';ctx.beginPath();ctx.ellipse(0,0,45,9,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=f.invuln>0&&Math.floor(elapsed*24)%2===0?.48:1;
 ctx.scale(face,1);
 // back leg
 ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#101724';ctx.lineWidth=20;ctx.beginPath();ctx.moveTo(-10,-62+duck);ctx.lineTo(-18+walk,-31);ctx.lineTo(-27+walk,0);ctx.stroke();ctx.strokeStyle=f.color;ctx.lineWidth=15;ctx.stroke();
 ctx.fillStyle='#141b29';rr(-43+walk,-7,31,11,5);ctx.fill();ctx.fillStyle=f.trim;ctx.fillRect(-18+walk,-6,9,3);
 // forward leg and kicks
 let legx=14,legy=-32;if(attack==='kick'&&active>.27&&active<.82){legx=55+active*32;legy=-53-(Math.sin(active*3)*6)}
 ctx.strokeStyle='#101724';ctx.lineWidth=21;ctx.beginPath();ctx.moveTo(11,-65+duck);ctx.lineTo(legx,-38);ctx.lineTo(legx+8,legy);ctx.stroke();ctx.strokeStyle=f.color;ctx.lineWidth=15;ctx.stroke();
 ctx.fillStyle='#172031';rr(legx+1,legy-5,34,11,5);ctx.fill();ctx.fillStyle=f.trim;ctx.fillRect(legx+23,legy-4,9,3);
 // torso, tapered gi silhouette
 ctx.fillStyle='#101724';ctx.beginPath();ctx.moveTo(-20,-127+duck);ctx.lineTo(20,-127+duck);ctx.lineTo(27,-77);ctx.lineTo(14,-60);ctx.lineTo(-18,-60);ctx.lineTo(-28,-83);ctx.closePath();ctx.fill();
 const body=ctx.createLinearGradient(-24,0,24,0);body.addColorStop(0,f.color);body.addColorStop(.52,f.side===1?'#18a8b8':'#c93662');body.addColorStop(1,f.color);ctx.fillStyle=body;ctx.beginPath();ctx.moveTo(-17,-125+duck);ctx.lineTo(17,-125+duck);ctx.lineTo(22,-82);ctx.lineTo(12,-65);ctx.lineTo(-16,-65);ctx.lineTo(-23,-84);ctx.closePath();ctx.fill();
 // crossed belt and diagonal jacket trim
 ctx.fillStyle='#111827';rr(-18,-82,36,8,2);ctx.fill();ctx.fillStyle=f.trim;ctx.fillRect(-18,-82,36,3);
 ctx.strokeStyle=f.trim;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-10,-122+duck);ctx.lineTo(12,-89);ctx.stroke();
 // arms. Punch arm stretches forward for active strike / fireball
 let punchReach=attack==='punch'&&active>.22&&active<.72?39:0,fireReach=attack==='fire'&&active>.2?27:0;
 // far arm
 ctx.strokeStyle='#111927';ctx.lineWidth=17;ctx.beginPath();ctx.moveTo(-17,-117+duck);ctx.lineTo(-30,-97+duck);ctx.lineTo(-20,-83+duck);ctx.stroke();ctx.strokeStyle=f.trim;ctx.lineWidth=12;ctx.stroke();ctx.fillStyle='#fff0d4';ctx.beginPath();ctx.arc(-20,-81+duck,8,0,Math.PI*2);ctx.fill();
 // near arm and glove
 let armEnd=29+punchReach+fireReach;let armY=-102+duck-(attack==='upper'?26:0);
 ctx.strokeStyle='#101724';ctx.lineWidth=21;ctx.beginPath();ctx.moveTo(16,-116+duck);ctx.lineTo(25,-105+duck);ctx.lineTo(armEnd,armY);ctx.stroke();ctx.strokeStyle=f.color;ctx.lineWidth=15;ctx.stroke();
 ctx.fillStyle=f.trim;ctx.beginPath();ctx.arc(armEnd+4,armY,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff1dc';ctx.beginPath();ctx.arc(armEnd+4,armY-2,7,0,Math.PI*2);ctx.fill();
 // collar and neck
 ctx.fillStyle='#f6c6a7';rr(-7,-139+duck,14,18,4);ctx.fill();
 // head
 ctx.fillStyle='#ffd2ae';ctx.beginPath();ctx.ellipse(0,-153+duck,20,23,0,0,Math.PI*2);ctx.fill();
 // hair silhouette
 ctx.fillStyle=f.side===1?'#121b2a':'#251321';ctx.beginPath();ctx.moveTo(-20,-154+duck);ctx.lineTo(-17,-173+duck);ctx.lineTo(-6,-180+duck);ctx.lineTo(9,-177+duck);ctx.lineTo(21,-164+duck);ctx.lineTo(17,-153+duck);ctx.lineTo(8,-162+duck);ctx.lineTo(-4,-158+duck);ctx.lineTo(-15,-150+duck);ctx.closePath();ctx.fill();
 if(f.side===1){ctx.fillStyle='#4cf2e9';ctx.beginPath();ctx.moveTo(-9,-176+duck);ctx.lineTo(3,-190+duck);ctx.lineTo(10,-174+duck);ctx.closePath();ctx.fill()}else{ctx.fillStyle='#ff637f';ctx.beginPath();ctx.moveTo(8,-176+duck);ctx.lineTo(24,-186+duck);ctx.lineTo(18,-168+duck);ctx.closePath();ctx.fill()}
 // eye / cheek marker
 ctx.fillStyle='#20253b';ctx.fillRect(6,-155+duck,5,2);ctx.fillStyle=f.trim;ctx.globalAlpha=.7;ctx.fillRect(11,-147+duck,5,2);ctx.globalAlpha=f.invuln>0&&Math.floor(elapsed*24)%2===0?.48:1;
 // chest sigil
 ctx.fillStyle=f.trim;ctx.globalAlpha=.9;ctx.beginPath();ctx.moveTo(0,-110+duck);ctx.lineTo(8,-101+duck);ctx.lineTo(0,-91+duck);ctx.lineTo(-8,-101+duck);ctx.closePath();ctx.fill();ctx.globalAlpha=1;
 // movement trail on dash
 if(attack==='dash'){ctx.globalAlpha=.2;ctx.fillStyle=f.color;ctx.beginPath();ctx.ellipse(-22,-88,44,20,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
 ctx.restore();
}
function drawEffects(){for(const b of projectiles){ctx.save();ctx.shadowColor=b.color;ctx.shadowBlur=24;const g=ctx.createRadialGradient(b.x,b.y,2,b.x,b.y,26);g.addColorStop(0,'#ffffff');g.addColorStop(.28,b.color);g.addColorStop(1,b.color+'00');ctx.fillStyle=g;ctx.beginPath();ctx.arc(b.x,b.y,27,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(b.x,b.y,7,0,Math.PI*2);ctx.fill();ctx.restore()}
 for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.shadowBlur=0;
 // fight floor markers
 ctx.globalAlpha=.24;ctx.strokeStyle='#d5efff';ctx.setLineDash([6,8]);ctx.beginPath();ctx.moveTo(58,FLOOR+7);ctx.lineTo(1222,FLOOR+7);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;
}
function drawOverlay(){if(paused){ctx.fillStyle='#090d1bd9';ctx.fillRect(0,0,W,H);panelText('PAUSED','PRESS ESC TO RETURN',640,325);return}
 if(roundState==='intro'){ctx.fillStyle='#090d1b55';ctx.fillRect(0,0,W,H);const label=intro>1.05?'ROUND  '+round:'FIGHT!';panelText(label,intro>1.05?'ROOFTOP SHOWDOWN':'MAKE YOUR MOVE',640,320);if(intro<.65){ctx.globalAlpha=(.65-intro)/.65;ctx.fillStyle='#fff';ctx.font='900 95px system-ui';ctx.textAlign='center';ctx.fillText('FIGHT!',640,420);ctx.globalAlpha=1}}
